     1	// HTTP helpers: reading a JSON body, sending JSON replies and turning errors into replies.
     2	import { ValidationError } from './validate.mjs'
     3	
     4	export const MAX_BODY_BYTES = 10 * 1024
     5	
     6	export class HttpError extends Error {
     7	  constructor(status, message) {
     8	    super(message)
     9	    this.status = status
    10	  }
    11	}
    12	
    13	// Reads the whole body as UTF-8. Past MAX_BODY_BYTES it stops keeping chunks but still drains the upload,
    14	// so the 413 reply reaches the client instead of a reset connection.
    15	export function readBody(req) {
    16	  return new Promise((resolve, reject) => {
    17	    const chunks = []
    18	    let size = 0
    19	    req.on('data', chunk => {
    20	      size += chunk.length
    21	      if (size <= MAX_BODY_BYTES) chunks.push(chunk)
    22	    })
    23	    req.on('end', () => {
    24	      if (size > MAX_BODY_BYTES) reject(new HttpError(413, 'body too large'))
    25	      else resolve(Buffer.concat(chunks).toString('utf8'))
    26	    })
    27	    req.on('error', reject)
    28	  })
    29	}
    30	
    31	export function parseJsonObject(text) {
    32	  let value
    33	  try {
    34	    value = JSON.parse(text)
    35	  } catch {
    36	    throw new HttpError(400, 'invalid JSON')
    37	  }
    38	  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    39	    throw new HttpError(400, 'body must be a JSON object')
    40	  }
    41	  return value
    42	}
    43	
    44	// Sends { status, body }: body as JSON, or no body at all when it is undefined (204).
    45	export function send(res, { status, body }) {
    46	  if (body === undefined) {
    47	    res.writeHead(status).end()
    48	    return
    49	  }
    50	  const text = JSON.stringify(body)
    51	  res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(text) })
    52	  res.end(text)
    53	}
    54	
    55	export function errorReply(err) {
    56	  if (err instanceof HttpError) return { status: err.status, body: { error: err.message } }
    57	  if (err instanceof ValidationError) return { status: 400, body: { error: err.message } }
    58	  // An OS error (ENOENT, EACCES, ...) is logged as one line; any other error keeps its stack.
    59	  console.error(err.code ? [err.code, err.syscall, err.path].filter(Boolean).join(' ') : err)
    60	  return { status: 500, body: { error: 'internal error' } }
    61	}
    62	// HTTP entry point: finds the route, reads the JSON body of the routes that take one, runs the handler and
    63	// saves the store after every change. Env: PORT (default 3000), DATA_FILE (default groups.json).
    64	import { existsSync } from 'node:fs'
    65	import { createServer } from 'node:http'
    66	import { dirname, resolve } from 'node:path'
    67	import { errorReply, parseJsonObject, readBody, send } from './lib/http.mjs'
    68	import { findRoute } from './lib/routes.mjs'
    69	import { load, save } from './lib/store.mjs'
    70	
    71	const DEFAULT_PORT = 3000
    72	const MAX_PORT = 65535
    73	
    74	// Builds the server around the store in dataFile. The store is kept in memory; each change is saved before it
    75	// replaces the in-memory copy, so a failed save changes nothing.
    76	export function createApp(dataFile) {
    77	  let state = load(dataFile)
    78	  return createServer(async (req, res) => {
    79	    try {
    80	      // Prefixing the origin keeps a request path like //host/groups a path, not a host.
    81	      const url = new URL(`http://localhost${req.url}`)
    82	      const route = findRoute(req.method, url.pathname)
    83	      if (!route) return send(res, { status: 404, body: { error: 'not found' } })
    84	      const body = route.takesBody ? parseJsonObject(await readBody(req)) : undefined
    85	      const reply = route.handler({ state, params: route.params, query: url.searchParams, body })
    86	      if (reply.state) {
    87	        save(dataFile, reply.state)
    88	        state = reply.state
    89	      }
    90	      send(res, reply)
    91	    } catch (err) {
    92	      send(res, errorReply(err))
    93	    }
    94	  })
    95	}
    96	
    97	function fail(message) {
    98	  console.error(`cannot start: ${message}`)
    99	  process.exitCode = 1
   100	}
   101	
   102	// A plain message for the OS errors a bad DATA_FILE gives; any other error keeps its own.
   103	function loadErrorMessage(err, file) {
   104	  if (err.code === 'EISDIR') return `DATA_FILE ${file} is a folder, not a file`
   105	  if (err.code === 'EACCES') return `cannot read DATA_FILE ${file}: permission denied`
   106	  return err.message
   107	}
   108	
   109	function main() {
   110	  const port = Number(process.env.PORT || DEFAULT_PORT)
   111	  if (!Number.isInteger(port) || port < 0 || port > MAX_PORT) {
   112	    return fail(`PORT must be a whole number from 0 to ${MAX_PORT}, got "${process.env.PORT}"`)
   113	  }
   114	  const file = process.env.DATA_FILE || 'groups.json'
   115	  // Without this check the server would start, then answer 500 to every change it cannot save.
   116	  if (!existsSync(dirname(resolve(file)))) return fail(`folder for DATA_FILE ${file} does not exist`)
   117	  let server
   118	  try {
   119	    server = createApp(file)
   120	  } catch (err) {
   121	    return fail(loadErrorMessage(err, file))
   122	  }
   123	  server.on('error', err => fail(err.message))
   124	  server.listen(port, '127.0.0.1', () => {
   125	    console.log(`listening on http://127.0.0.1:${server.address().port}`)
   126	  })
   127	}
